void FCM_NewMacro()
{

ICD_PUSH(2);


  FC_MARKER(3);

  FC_MARKER(4);

  // Delay, Type: Delay: 1 ms
  FCI_DELAYBYTE_MS(1);

  FC_MARKER(5);

ICD_POP();


}

