/*========================================================================*\
   Use :Main
\*========================================================================*/
int main()
{
	MCUSR=0x00;
	MCUSR=0x00;
	wdt_disable();


	//Enable initial stop condition
	dbg_mode = 0x08;

	ICD_PUSH(0);


  FC_MARKER(6);

  FC_MARKER(7);

  // Interrupt, Type: Interrupt: Enable TMR1
  TCCR1B &= 0xf8;
  TCCR1B |= 0x05;
  sei();
  TIMSK1 |= (1 << TOIE1);

  FC_MARKER(13);

  // Loop, Type: Loop: While 1
  while (1)
  {
    FC_MARKER(13);

    if ((1) == 0) break;
    FC_MARKER(9);

    // Calculation, Type: Calculation:
    // count = count + 1
    FCV_COUNT = FCV_COUNT + 1;

    FC_MARKER(10);

    // Output, Type: Output: count -> PORTB
    SET_PORT(B,(FCV_COUNT));

    FC_MARKER(11);

    // User Macro, Type: User Macro: NewMacro()
    FCM_NewMacro();

    FC_MARKER(12);

    // Delay, Type: Delay: 100 ms
    FCI_DELAYBYTE_MS(100);

    FC_MARKER(8);

  }

  FC_MARKER(14);

	ICD_POP();

	//Code to signal end of program to ICD
	dbg_mode = 0x08;

	FC_MARKER(-1);


	mainendloop: goto mainendloop;
}

